# Tur R yamasi (25 Ekim 2026): kitap sozlugu. app/data/kitap_sozlugu.tsv (303 kayit; 34 kitapta sozlukte olmayan, Claude'un okuyarak
# sectigi kelime ve adlar), dictionary.py'de yukleme (duzeltmeler'den sonra, Hayrat'tan once), tests/test_tur_r.py, test_kok'ta safran zaferan.
# Kod klasorunde calistirilir. Tekrar calistirilabilir (yapilmissa ATLANDI); beklenen metin yoksa HATA ile durur.
import os, sys

def oku(p):
    return open(p, encoding="utf-8").read()

def yaz(p, s):
    open(p, "w", encoding="utf-8").write(s)

if not os.path.isfile("app/engine/dictionary.py"):
    print("HATA: kod klasorunde degilsiniz"); sys.exit(1)

def degistir(p, ad, eski, yeni):
    s = oku(p)
    if yeni in s:
        print("ATLANDI:", ad)
    elif s.count(eski) == 1:
        yaz(p, s.replace(eski, yeni)); print("YAPILDI:", ad)
    else:
        print("HATA: beklenen metin bulunamadi:", ad); sys.exit(1)

